import{_ as i,o as a,c as e,a5 as t}from"./chunks/framework.CXroN2RO.js";const h=JSON.parse('{"title":"第7章 コンパイラ・リンカ・実行ファイル(ELF/PE)・ABI","description":"","frontmatter":{"title":"第7章 コンパイラ・リンカ・実行ファイル(ELF/PE)・ABI","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"「ビルド」ボタンの中身は最大級のブラックボックスだ。UE5のビルドは 数千の翻訳単位のコンパイルとリンクであり、リンクエラー(未解決シンボル、 重複定義)、DLL境界の問題、ABI非互換クラッシュ、ビルド時間との戦いは"}},"headers":[],"relativePath":"guide/low-level/compiler-linker-executable.md","filePath":"guide/low-level/compiler-linker-executable.md"}'),n={name:"guide/low-level/compiler-linker-executable.md"};function o(s,l,r,d,c,p){return a(),e("div",null,[...l[0]||(l[0]=[t(`<h1 id="第7章-コンパイラ・リンカ・実行ファイル-elf-pe-・abi" tabindex="-1">第7章 コンパイラ・リンカ・実行ファイル(ELF/PE)・ABI <a class="header-anchor" href="#第7章-コンパイラ・リンカ・実行ファイル-elf-pe-・abi" aria-label="Permalink to &quot;第7章 コンパイラ・リンカ・実行ファイル(ELF/PE)・ABI&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>「ビルド」ボタンの中身は最大級のブラックボックスだ。UE5のビルドは 数千の翻訳単位のコンパイルとリンクであり、リンクエラー(未解決シンボル、 重複定義)、DLL境界の問題、ABI非互換クラッシュ、ビルド時間との戦いは エンジンプログラマの日常である。「EXEとは何か」を知ることは、 第8章「OSがEXEをどう実行するか」の直接の前提でもある。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>コンパイルの各段階(前処理→構文解析→最適化→コード生成)を説明できる</li><li>オブジェクトファイル・シンボル・再配置を説明でき、リンクエラーを自力で読める</li><li>PE(Windows)/ELF(Linux)の構造(セクション、インポート/エクスポート)を概説できる</li><li>静的リンクと動的リンク(DLL)の違い、DLL境界の注意点を説明できる</li><li>ABIとは何か、なぜC++ライブラリのバイナリ配布が難しいかを説明できる</li><li>最適化がUBを前提に行われることを理解し、実例を読める</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第4章(アセンブリ・呼出規約)、第5章(C・翻訳単位)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>コンパイラパイプライン</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.cpp → [前処理] → [字句/構文解析→AST] → [意味解析]</span></span>
<span class="line"><span>     → [中間表現(IR)] → [最適化] → [コード生成] → .obj</span></span></code></pre></div><ul><li>前処理(#include展開)で1ファイルが数十万行になる現実</li><li>最適化の代表例: 定数畳み込み、インライン展開、ループ不変式移動、 デッドコード除去、自動ベクトル化</li><li><strong>UBと最適化</strong>: 「UBは起きない」前提で最適化される (例: 符号付きオーバーフロー前提のループ変換、null検査の削除)</li><li>デバッグビルド(-Od)とリリースビルド(-O2)の本質的な差</li></ul></li><li><strong>オブジェクトファイルとシンボル</strong><ul><li>.obj = 機械語 + シンボルテーブル + 再配置情報</li><li>定義済みシンボル/未解決シンボル。<code>dumpbin /symbols</code> で見る</li><li>C++の<strong>名前修飾(マングリング)</strong>: <code>?Update@Player@@QEAAXM@Z</code> ── オーバーロードの実現方法。<code>extern &quot;C&quot;</code> の意味</li></ul></li><li><strong>リンカ</strong><ul><li>仕事は2つ: シンボル解決 + 再配置(アドレス確定)</li><li>静的ライブラリ(.lib)=objの束。リンク順の罠</li><li><strong>LNK2019(未解決)/LNK2005(重複)を構造から理解する</strong></li><li>ODR(One Definition Rule)とinline、テンプレートの暗黙的重複排除</li><li>インクリメンタルリンク、LTO/LTCG(リンク時最適化)</li></ul></li><li><strong>実行ファイルフォーマット: PE と ELF</strong><ul><li>セクション: .text/.data/.rdata/.bss、ヘッダ、エントリポイント</li><li>PE(Windows): インポートテーブル(IAT)/エクスポート、<code>dumpbin /headers</code></li><li>ELF(Linux/多くのコンソールの親戚): <code>readelf -a</code> で観察(WSL)</li><li>main()の前に走るもの: CRT起動コード(mainCRTStartup)、 グローバルコンストラクタ ── 「main前クラッシュ」の正体</li></ul></li><li><strong>動的リンク(DLL/共有ライブラリ)</strong><ul><li>ロード時リンクと実行時(LoadLibrary/GetProcAddress)</li><li>__declspec(dllexport/dllimport)、UEの <code>MODULENAME_API</code> マクロの正体</li><li><strong>DLL境界の掟</strong>: 確保と解放は同じ側で/CRT混在問題/ STL型をDLL境界で渡す危険</li><li>ホットリロード(ゲームエンジンのC++リロードはDLL再ロードで実現)</li></ul></li><li><strong>ABI(Application Binary Interface)</strong><ul><li>呼出規約(第4章)+構造体レイアウト+マングリング+例外/vtable表現の総体</li><li>「C++にはABI標準がない」→ コンパイラ/バージョン違いのバイナリ混在は危険</li><li>ゲーム業界でC APIがプラグイン境界に使われる理由</li></ul></li><li><strong>ビルドシステム</strong><ul><li>なぜMakeやCMakeが要るのか(依存グラフと差分ビルド)</li><li>UEのUnrealBuildTool・Unity(C#コンパイル+IL2CPP)は この章の仕組みの自動化にすぎない</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>翻訳単位は独立にコンパイルされ、リンカが繋ぐ</strong> ── C/C++ビルドモデルの核心</li><li><strong>シンボル</strong> ── 関数・変数の「名前と住所」の台帳</li><li><strong>実行ファイル=OSへの積み込み指示書</strong>(第8章へ直結)</li><li><strong>ABI=バイナリレベルの互換性契約</strong></li><li><strong>最適化はUBを前提とする</strong> ── 「-O2でだけ壊れる」の正体</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>LNK2019/LNK2005との格闘</td><td>シンボル解決・ODR</td></tr><tr><td>UEのモジュール(.Build.cs)とDLL群</td><td>動的リンク・エクスポート</td></tr><tr><td>プラグインSDKがC APIな理由</td><td>ABI非互換</td></tr><tr><td>リリースビルドでだけ挙動が変わる</td><td>最適化とUB</td></tr><tr><td>ビルド20分…を速くしたい</td><td>翻訳単位・ヘッダ依存・LTO</td></tr><tr><td>main前にクラッシュ</td><td>グローバルコンストラクタ・CRT</td></tr><tr><td>C++ホットリロード</td><td>DLL再ロード</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>2つの.cppからなるプログラムを<strong>コマンドラインで</strong> <code>cl /c</code> →<code>link</code> と 段階を分けてビルドせよ。<code>dumpbin /symbols</code> でシンボルを観察せよ。</li><li>わざとLNK2019とLNK2005を起こし、エラーメッセージの マングリング名を<code>undname</code>で復元して読め。</li><li>簡単なDLLを作り、(a)インポートライブラリ経由 (b)LoadLibrary/ GetProcAddress経由 の両方で呼び出せ。</li><li><code>dumpbin /headers /imports</code> で自作EXEと(観察用に)ゲームのEXEの セクション・インポートDLL一覧を眺めよ。WSLでは <code>readelf -S</code> で ELFと比較せよ。</li><li>Compiler Explorerで、符号付きオーバーフローUBを含むループが -O2でどう「豪快に」最適化されるか観察せよ。</li><li><strong>ミニコンパイラ</strong>: Rui Ueyama「低レイヤを知りたい人のための Cコンパイラ作成入門」(Web無料)の最初の数ステップ (整数→四則演算→比較)を写経し、「ソース→アセンブリ出力」を体験せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>坂井弘亮『リンカ・ローダ実践開発テクニック』── 和書の決定版</li><li>Rui Ueyama「低レイヤを知りたい人のためのCコンパイラ作成入門」(Web)</li><li>John Levine &quot;Linkers and Loaders&quot; ── 古典</li><li>『Windows Internals』第3章あたり(PEローダ、第8章と併読)</li><li>ドラゴンブック(『コンパイラ 原理・技法・ツール』)は<strong>発展編送り</strong>。 ゲームプログラマは最適化章の拾い読みで十分</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>chibicc</strong>(rui314/chibicc)── 読める本物のCコンパイラ(約1万行)</li><li><strong>mold</strong>(rui314/mold)── 爆速リンカ。READMEの設計解説だけでも</li><li>LLVM ── 発展編で。今は「存在と役割」を知ればよい</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Matt Godbolt CppCon &quot;The Bits Between the Bits: How We Get to main()&quot; ── 起動シーケンスの決定版講演</li><li>Rui Ueyama氏のリンカ/コンパイラ講演(YouTube)</li><li>CppCon &quot;What Has My Compiler Done for Me Lately?&quot;(Godbolt)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>chibicc(main.c → tokenize → parse → codegen の流れ)</li><li>UE5の任意モジュールの <code>*.Build.cs</code> と <code>*_API</code> マクロ定義</li><li>CRTのエントリポイント(VS付属の <code>exe_common.inl</code> を眺める)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>コンパイラとリンカの役割分担を「シンボル」の言葉で説明せよ。</li><li>LNK2019とLNK2005はそれぞれ何が起きているか。</li><li>inline関数やテンプレートがヘッダに書けるのはなぜか(ODRとの関係)。</li><li>DLLとstaticライブラリの違い。DLL境界でnew/deleteを跨いではいけない理由。</li><li>ABIとは何か。C++ライブラリをバイナリ配布しにくい理由を3つ。</li><li>EXEの.text/.data/.rdataセクションにはそれぞれ何が入っているか。</li><li>「リリースビルドでだけバグる」の代表的な原因を2系統挙げよ (UB系・未初期化系)。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[開発時]</span></span>
<span class="line"><span> あなたのC++ ──(コンパイラ)──&gt; .obj群 ──(リンカ)──&gt; Game.exe + 多数のDLL</span></span>
<span class="line"><span>      │ UEなら: UBTがモジュール毎にDLL化 / Unityなら: C#→IL→IL2CPP→C++→この流れ</span></span>
<span class="line"><span>[起動時]</span></span>
<span class="line"><span> Game.exe ──&gt; OSのPEローダが .text/.dataをメモリへ配置(第8章)</span></span>
<span class="line"><span>          ──&gt; インポートテーブルで d3d12.dll / xinput1_4.dll 等を解決</span></span>
<span class="line"><span>          ──&gt; CRT起動 → グローバルコンストラクタ → WinMain → ゲームループへ</span></span>
<span class="line"><span>[実行時]</span></span>
<span class="line"><span> ホットリロード = DLLの再ロード / プラグイン = LoadLibrary</span></span>
<span class="line"><span> クラッシュダンプの関数名表示 = シンボル情報(PDB)</span></span></code></pre></div>`,28)])])}const L=i(n,[["render",o]]);export{h as __pageData,L as default};
